import json, base64, hashlib, struct
from pathlib import Path

root = Path("/tmp/opensip-design-corrections/consumer-b.v12-fresh-other-runs-full-review.v1/exports")
out = Path("/tmp/opensip-design-corrections/consumer-b.v12-fresh-other-runs-full-review.v1/output/extracted")

PREFIX = b"opensip.product.v1\x00"

def parse_h_frame(raw):
    if not raw.startswith(PREFIX):
        return None
    rest = raw[len(PREFIX):]
    # domain \x00 uint64BE len || C(X)
    z = rest.find(b"\x00")
    if z < 0:
        return {"error": "no domain NUL"}
    domain = rest[:z].decode("ascii")
    rest = rest[z+1:]
    if len(rest) < 8:
        return {"error": "short length"}
    (n,) = struct.unpack(">Q", rest[:8])
    payload = rest[8:]
    if len(payload) != n:
        return {"error": f"len mismatch declared={n} actual={len(payload)}", "domain": domain}
    try:
        obj = json.loads(payload.decode("utf-8"))
    except Exception as e:
        return {"error": f"json {e}", "domain": domain, "n": n}
    return {"domain": domain, "payload": obj, "payloadBytes": n}

def load_store(name):
    data = json.loads((root/name).read_text())
    blobs = {k: base64.b64decode(v) for k,v in data["blobs"].items()}
    ot = data["objectTable"]
    return ot, blobs

for name in ["ts.store.json","rust.store.json","syntax-data.store.json","rust-partial-clones.store.json"]:
    ot, blobs = load_store(name)
    print("="*80)
    print(name)
    # find run
    run_keys = [k for k in ot if k.startswith("run3:")]
    print("run keys", run_keys)
    for rk in run_keys:
        digest = ot[rk]["digest"]
        raw = blobs[digest]
        fr = parse_h_frame(raw)
        print("RUN domain", fr.get("domain") if fr else None)
        print(json.dumps(fr.get("payload") if fr else fr, indent=2)[:2000])
    # proof
    for pk in [k for k in ot if k.startswith("proof3:")]:
        digest = ot[pk]["digest"]
        raw = blobs[digest]
        fr = parse_h_frame(raw)
        p = fr.get("payload") if fr else None
        print("PROOF keys", list(p.keys()) if isinstance(p, dict) else p)
        if isinstance(p, dict):
