import json, base64, hashlib, struct
from pathlib import Path

root = Path("/tmp/opensip-design-corrections/consumer-b.v12-fresh-other-runs-full-review.v1/exports")
PREFIX = b"opensip.product.v1\x00"

def parse_h_frame(raw):
    if not raw.startswith(PREFIX):
        return None
    rest = raw[len(PREFIX):]
    z = rest.find(b"\x00")
    domain = rest[:z].decode("ascii")
    rest = rest[z+1:]
    (n,) = struct.unpack(">Q", rest[:8])
    payload = rest[8:]
    obj = json.loads(payload.decode("utf-8"))
    return domain, obj, payload

def load(name):
    data = json.loads((root/name).read_text())
    blobs = {k: base64.b64decode(v) for k,v in data["blobs"].items()}
    ot = data["objectTable"]
    return ot, blobs

def get_by_label(ot, blobs, label, kind=None):
    out=[]
    for k,m in ot.items():
        if m.get("label")==label and (kind is None or m.get("kind")==kind):
            d = m.get("digest") or (k.split(":",1)[1] if ":" in k else k)
            raw = blobs[d]
            fr = parse_h_frame(raw)
            if fr:
                out.append((k, m, fr[0], fr[1]))
            else:
                try:
                    out.append((k, m, None, json.loads(raw.decode())))
                except Exception:
                    out.append((k, m, None, {"_len": len(raw), "_prefix": raw[:24]}))
    return out

for name in ["ts.store.json"]:
    ot, blobs = load(name)
    for lab in ["ts-context","ts-universe","plan","enum","analysis-spec","policy","rule-program","ExecutionInputsV1","covp-file","covp-clones","clones-payload-index","file-payload-src/index.ts","sinv-0-file","sinv-1-symbol","membership","grant","waivers","ScopeDocumentV1","emis","witness-p","program-predicate-p","ResolvedNodeModulesLayoutV1","TypeScriptConfigGraphV1"]:
        recs = get_by_label(ot, blobs, lab)
        print("="*60, lab, "n", len(recs))
        for k,m,dom,obj in recs[:1]:
            if isinstance(obj, dict):
                print("domain", dom, "keys", list(obj.keys())[:30])
                print(json.dumps(obj, indent=2)[:2200])
            else:
                print(obj)
